  height: 1px;
  background: linear-gradient(90deg, transparent, var(--border-medium), transparent);
  margin: 3rem 0;
}

/* --- Launch CTA Section --- */
.launch-grid {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .launch-grid {
    grid-template-columns: repeat(2, 1fr);
  }
