  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.launch-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.launch-card p {
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

/* --- Community Grid --- */
.community-grid {
  display: grid;
  gap: 1rem;
}

@media (min-width: 640px) {
  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.community-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  color: var(--text-primary);
  transition: all var(--transition-base);
}

.community-card:hover {
  border-color: var(--border-medium);
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.community-card .icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.125rem;
}

.community-card span {
  font-weight: 500;
  font-size: 0.9375rem;
}

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  max-width: 600px;
  margin: 0 auto;
}

@media (min-width: 640px) {
  .protocol-diagram {
    grid-template-columns: repeat(4, 1fr);
  }
}

.protocol-actor {
  text-align: center;
  padding: 1.5rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.protocol-actor:hover {
  border-color: var(--border-accent);
  transform: translateY(-2px);
}

.protocol-actor .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.75rem;
  font-size: 1.5rem;
}

.protocol-actor h4 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.protocol-actor p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Support Categories --- */
.support-grid {
  display: grid;
  gap: 1rem;
}

@media (min-width: 640px) {
  .support-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.support-card {
  padding: 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.support-card:hover {
  border-color: var(--border-medium);
  background: var(--bg-secondary);
}

.support-card h4 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.support-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--border-medium);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* --- Print --- */
@media print {
  .site-header, .sidebar, .site-footer { display: none; }
  .main-content { margin-left: 0; }
}

